"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[894],{7894:function(e,s,a){a.d(s,{AK:function(){return t},TG:function(){return o},VY:function(){return c}});let t=[{id:"tantrum",label:"가게에서 드러누웠을 때"},{id:"bedtime",label:"안 자겠다고 버틸 때"},{id:"meal",label:"밥을 안 먹을 때"}],c=[{id:"baby",label:"돌 전"},{id:"toddler",label:"돌부터 세 살까지"},{id:"preschool",label:"네 살부터 입학까지"}],o={balanced:{about:"심리학자 다이애나 바움린드가 1960년대에 부모의 모습을 관찰하며 정리한 양육 유형에서 왔어요. 따뜻함과 요구를 두 축으로 보고, 둘 다 높은 모습을 권위 있는 양육이라고 불러요. 정해진 교구나 규칙보다 연구에서 자주 지지받는 방법을 상황에 맞게 골라 쓰는 쪽이에요.",principles:["아이의 감정은 받아 주고, 행동의 한계는 지켜요.","규칙에는 이유를 말해 주고, 나이에 맞게 의견도 들어요.","규칙은 적게 두고 정한 것은 꾸준히 지켜요."],scenes:{tantrum:'"갖고 싶었구나. 오늘은 안 사." 짧게 말하고, 가라앉을 때까지 안전한 곳에서 곁에 있어요. 울어도 결정은 바꾸지 않아요.',bedtime:'자는 시간과 순서를 정해 두고 그대로 해요. "책 두 권 읽고 불 끌 거야"라고 미리 말하고, 끝나면 짧게 인사하고 나와요.',meal:"무엇을 차릴지는 부모가, 얼마나 먹을지는 아이가 정해요. 안 먹어도 혼내지 않고, 식사 시간이 끝나면 치워요."},ages:{baby:"울음에 따뜻하게 답하면서 먹고 자는 흐름을 조금씩 만들어요.",toddler:"안 되는 것 몇 가지를 분명히 하고, 나머지는 둘 중 하나를 고르게 해요.",preschool:"규칙의 이유를 함께 이야기하고, 지키지 못했을 때 어떻게 할지도 미리 정해요."},takes:"돈이나 준비물은 거의 들지 않아요. 대신 그때그때 판단이 계속 필요하고, 피곤한 날에도 같은 기준을 지켜야 해요.",evidence:"권위 있는 양육은 여러 나라의 연구에서 아이의 적응, 학업과 함께 나타나는 일이 많았어요. 다만 대부분 관찰 연구라 원인이라고 단정할 수는 없고, 문화에 따라 다르게 나타나기도 해요.",compass:"따뜻하게 받아 주면서 지킬 선은 무엇일까요?"},montessori:{about:"이탈리아의 의사 마리아 몬테소리가 1907년 로마의 어린이집에서 아이들을 관찰하며 만든 교육법이에요. 아이에게는 스스로 배우려는 힘이 있다고 보고, 어른은 가르치기보다 환경을 준비해요. 집에서는 교구보다 낮은 선반, 작은 도구, 혼자 할 시간이 먼저예요.",principles:["아이 키와 손에 맞게 환경을 준비해요.","할 일을 아이가 고르고, 집중하고 있으면 끊지 않아요.","어른은 관찰하고, 필요한 만큼만 도와요.","실수는 혼낼 일이 아니라 스스로 고쳐 볼 기회로 봐요."],scenes:{tantrum:'가라앉기를 기다린 뒤 "장바구니에 이것 담아 줄래?" 하고 할 일을 줘요. 다음부터는 가게에 가기 전에 아이가 맡을 일을 정해요.',bedtime:"낮은 잠자리와 어두운 조명으로 스스로 눕기 쉽게 만들어요. 잠옷 고르기, 불 끄기처럼 아이가 할 수 있는 순서를 맡겨요.",meal:"작은 그릇과 수저를 주고 스스로 덜어 먹게 해요. 흘리면 같이 닦아요. 식탁 차리기도 아이 몫으로 줘요."},ages:{baby:"움직이기 좋은 옷과 안전한 바닥을 마련하고, 스스로 뻗고 잡는 것을 지켜봐요.",toddler:"옷 입기, 물 따르기, 닦기처럼 실제 생활의 일을 아이 크기로 맡겨요.",preschool:"시간이 걸려도 하루의 일을 스스로 계획하고 끝내도록 기다려요."},takes:"교구를 다 살 필요는 없지만 집을 손보는 품이 들어요. 어른이 하면 빠른 일을 기다려 줘야 해서 바쁜 아침이 가장 힘들어요.",evidence:"미국 공립 몬테소리 유치원에 추첨으로 들어간 아이들을 따라간 연구에서 학업과 사회성 이해가 더 높게 나왔어요. 다만 규모가 작아 저자들도 더 큰 연구가 필요하다고 했고, 가정에서의 실천을 직접 살핀 연구는 드물어요.",compass:"아이가 스스로 할 수 있게 무엇을 바꿔 둘 수 있을까요?"},gentle:{about:"심리학자 존 가트맨이 부모가 아이의 감정에 답하는 방식을 연구하며 정리한 감정코칭과, 벌 대신 연결을 앞세우는 젠틀 페어런팅 흐름을 묶은 방향이에요. 감정을 먼저 받아 주면 아이가 자기 마음을 다루는 법을 배운다고 봐요. 모든 행동을 받아 주는 것은 아니에요. 감정은 받아 주되 행동에는 선을 그어요.",principles:["작은 감정도 아이와 가까워질 기회로 봐요.","감정에 이름을 붙이고, 공감하며 들어요.","행동의 한계는 감정이 가라앉은 뒤 함께 찾아요.","부모의 감정도 돌봐요. 부모가 먼저 차분해져야 할 수 있어요."],scenes:{tantrum:'눈높이로 앉아 "정말 갖고 싶었구나, 속상하지" 하고 말해요. 진정되면 "오늘은 안 사. 사진 찍어 둘까?" 하고 같이 다음을 찾아요.',bedtime:'"더 놀고 싶구나" 하고 마음을 먼저 말해 주고, 잠자리에서 오늘 있었던 일을 잠깐 나눠요. 그래도 자는 시간은 그대로예요.',meal:'억지로 먹이지 않고 "오늘은 이게 싫구나" 하고 받아 줘요. 왜 싫은지, 무슨 맛 같은지 물어보며 음식과의 긴장을 줄여요.'},ages:{baby:'울음의 뜻을 살피고, 말을 못 해도 "배고팠구나" 하고 말로 옮겨 줘요.',toddler:'떼쓰는 순간에 감정 낱말을 들려줘요. 때리는 행동에는 "때리면 안 돼"를 같이 말해요.',preschool:"속상했던 일을 돌아보며 다음엔 어떻게 할지 아이가 먼저 말하게 도와요."},takes:"돈은 들지 않지만 마음이 많이 들어요. 부모가 지쳐 있으면 가장 하기 어렵고, 시간도 오래 걸려요.",evidence:"감정코칭을 가르치는 부모 프로그램은 무작위 비교 연구에서 부모의 반응이 바뀌고 아이 행동이 나아졌다는 보고가 있어요. 다만 젠틀 페어런팅이라는 이름은 정의가 넓어서 그 자체를 살핀 연구는 적어요.",compass:"지금 아이의 마음에 이름을 붙이면 무엇일까요?"},nordic:{about:"노르웨이와 스웨덴에서 이어져 온 프릴루프츠리브(자연 속 생활) 문화와 숲 유치원에서 온 방향이에요. 날씨가 나쁜 날은 없고 옷이 안 맞는 날이 있을 뿐이라는 말로 자주 소개돼요. 일찍 가르치기보다 바깥에서 몸으로 놀고, 스스로 해 보며 위험을 가늠하는 경험을 앞에 둬요.",principles:["날씨와 상관없이 매일 바깥에 나가요.","어른이 짜 주지 않은 자유 놀이를 넉넉히 둬요.","작은 위험은 치워 주기보다 스스로 가늠하게 해요.","일찍 배우는 것보다 천천히 자라는 것을 믿어요."],scenes:{tantrum:"크게 반응하지 않고 곁에서 기다렸다가 밖으로 데리고 나가요. 몸을 움직이고 바람을 쐬면 가라앉는 경우가 많다고 봐요.",bedtime:"낮에 바깥에서 충분히 움직이게 해요. 저녁은 느긋하게 보내고, 날이 좋으면 창을 살짝 열어 시원하게 재우기도 해요.",meal:"바깥에서 놀고 온 뒤 배가 고플 때 함께 앉아요. 소박한 음식을 내고 먹는 양은 재촉하지 않아요."},ages:{baby:"옷을 든든히 입혀 유모차로 매일 바깥바람을 쐬어요. 추운 날이나 더운 날은 아이 상태를 자주 살펴요.",toddler:"흙과 물, 나뭇가지로 놀게 해요. 비 오는 날에도 옷만 맞춰 나가요.",preschool:"오르기, 달리기처럼 조금 어려운 놀이를 곁에서 지켜보고, 숲 놀이를 넓혀 가요."},takes:"바깥 옷과 시간이 들어요. 미세먼지가 심한 날, 근처에 나갈 곳이 없는 동네, 부모가 함께 나가기 어려운 평일에는 그대로 하기 어려워요.",evidence:"숲 유치원과 숲 학교 연구를 모은 검토들은 운동 능력과 자연과의 친밀감 등에서 좋은 쪽의 결과를 보고해요. 하지만 연구 규모가 작고 방법에 한계가 많아서 더 탄탄한 연구가 필요하다고 해요.",compass:"바깥에서, 또는 아이 스스로 해 볼 수 있는 쪽은 무엇일까요?"},french:{about:"프랑스 가정의 생활 모습에서 온 방향이에요. 미국 언론인 파멜라 드러커맨이 파리에서 아이를 키우며 쓴 책으로 널리 알려졌어요. 카드르(테두리)라는 큰 틀은 엄격하게, 그 안에서는 자유롭게 둬요. 아이는 기다리는 법을 배우고, 어른의 시간과 부부의 삶도 아이만큼 존중해요.",principles:["큰 틀은 단호하게, 그 안에서는 자유롭게 둬요.","기다리는 힘을 일상에서 길러요.","먹는 시간을 정하고 어른과 같은 음식을 맛보게 해요.","부모도 자기 삶이 있는 사람으로 살아요."],scenes:{tantrum:'조용하고 단호하게 "안 돼. 그건 오늘 안 사." 하고 말해요. 길게 설명하거나 달래지 않고, 가라앉을 때까지 차분히 기다려요.',bedtime:'저녁 뒤부터 어른의 시간이에요. "이제 네 방에 있을 시간이야"라고 말하고, 아기라면 울음에 바로 달려가기 전에 잠깐 살펴봐요.',meal:'정해진 때에 다 같이 앉아 코스처럼 차려요. 간식은 오후에 한 번이고, "한 입만 맛보자"는 권하되 억지로 다 먹이지 않아요.'},ages:{baby:"깬다고 바로 안지 않고 잠깐 살펴보며 스스로 다시 잠드는 틈을 줘요. 배고프거나 아픈 울음이면 바로 가요.",toddler:'"잠깐만"을 일상에서 쓰고, 먹는 시간과 자는 시간을 일정하게 지켜요.',preschool:"인사와 식탁 예절을 익히고, 어른끼리 이야기할 때는 끼어들지 않고 기다리게 해요."},takes:"돈은 거의 들지 않아요. 아이가 울거나 조를 때 흔들리지 않는 마음이 필요하고, 주변에서 차갑다는 말을 들을 수 있어요. 어린이집과 식문화가 받쳐 주는 프랑스 환경과는 다른 점도 있어요.",evidence:"널리 알려진 내용은 주로 언론인의 관찰기에서 왔어요. 프랑스식이라는 묶음을 다른 방식과 비교한 연구는 찾기 어려워요. 정해진 수면 순서처럼 일부 실천은 따로 연구가 있어요.",compass:"우리 집의 큰 틀은 무엇이고, 그 안에서 아이가 정할 수 있는 것은 무엇일까요?"},japanese:{about:"일본 유치원과 가정에서 이어져 온 오모이야리(남을 헤아리는 마음)와 자기 몫을 챙기는 전통에서 온 방향이에요. 일본 유치원을 관찰한 연구자들은 교사가 다툼에 바로 끼어들지 않고 지켜보는 미마모루(지켜보기)에 주목했어요. 또래 속에서 부딪히며 스스로 풀어 보는 것을 중요하게 봐요.",principles:["다른 사람의 마음을 먼저 헤아려 보게 해요.","자기 물건과 자기 일은 스스로 챙겨요.","다툼에 바로 끼어들지 않고 곁에서 지켜봐요.","인사와 정리처럼 함께 사는 습관을 반복해요."],scenes:{tantrum:'곁에서 조용히 기다렸다가 "다른 분들이 놀라셨겠다. 진정되면 같이 가자"고 말해요. 크게 야단치지 않고, 함께 있는 사람들을 떠올리게 해요.',bedtime:"장난감과 내일 가방을 스스로 정리하는 것을 잠자리 순서에 넣어요. 온 가족이 같은 흐름으로 하루를 닫아요.",meal:"다 같이 인사하고 먹기 시작해요. 음식을 만든 사람을 떠올리게 하고, 먹은 그릇은 스스로 가져다 놓아요."},ages:{baby:"몸을 가까이하며 달래고, 가족의 일상 속에서 인사와 말소리를 들려줘요.",toddler:"자기 신발 놓기, 가방 걸기 같은 자기 몫을 하나씩 줘요. 친구와 부딪히면 잠깐 지켜봐요.",preschool:"또래 사이에서 차례와 양보를 겪게 하고, 집안일 하나를 당번처럼 맡겨요."},takes:"돈은 거의 들지 않지만 끼어들고 싶은 순간을 참아야 해요. 또래와 부딪힐 자리가 있어야 잘 맞아요. 아이가 맞고 있거나 다칠 수 있는 다툼은 지켜보는 대상이 아니에요.",evidence:"일본 유치원 연구는 주로 교실을 깊이 관찰한 질적 연구예요. 문화의 모습은 잘 보여 주지만 다른 방식과 결과를 비교한 것은 아니고, 가정에서의 실천은 더 드물어요.",compass:"지금 다른 사람의 마음과 아이 자신의 몫은 무엇일까요?"},achievement:{about:"높은 기대와 반복 연습을 강조하는 동아시아 학습 문화에서 온 방향이에요. 잘하게 되는 것은 타고나는 것보다 노력에 달렸고, 해냈다는 경험이 자신감을 만든다고 봐요. 에이미 추아의 책으로 타이거 맘이라는 말이 널리 퍼졌지만, 이 앱에서는 압박이 아니라 목표와 꾸준함에 초점을 둬요.",principles:["작은 목표를 분명히 하고 조금씩 높여요.","길게 하는 것보다 매일 반복해요.","재능보다 끝까지 한 과정을 칭찬해요.","틀린 것은 혼낼 일이 아니라 다시 해 볼 자리로 봐요."],scenes:{tantrum:'울음이 끝나면 "다음에는 먼저 말로 부탁하자. 한번 해 볼까?" 하고 바로 연습해 봐요. 해내면 어떻게 했는지 짚어 줘요.',bedtime:"자는 시간을 약속으로 정해요. 잠자리 정리를 스스로 해내는 것을 작은 목표로 삼고, 달력 대신 말로 인정해 줘요.",meal:'"오늘은 한 입 더 먹어 볼까"처럼 아주 작은 목표를 함께 정해요. 해내면 과정을 말해 주고, 음식을 상이나 벌로 쓰지 않아요.'},ages:{baby:"기대보다 반복이에요. 같은 노래, 같은 놀이를 꾸준히 해 주고 새로 해낸 것을 알아봐 줘요.",toddler:"혼자 신발 신기처럼 작은 일을 끝까지 하게 기다려요.",preschool:"아이가 좋아하는 것 하나를 골라 짧게 매일 연습해요. 학습지를 늘리는 것과는 달라요."},takes:"시간과 꾸준함이 많이 들고, 비용이 드는 활동으로 번지기 쉬워요. 아이가 즐거움을 잃는지 계속 살펴야 해요.",evidence:"중국계 미국인 가정을 여덟 해 동안 따라간 연구에서, 따뜻하게 지지하는 부모의 아이가 압박이 강한 타이거 양육의 아이보다 성적은 높고 우울감은 적었어요. 높은 기대 자체보다 따뜻함과 함께 있는지가 중요할 수 있어요.",compass:"아이가 해 볼 만한 다음 작은 한 걸음은 무엇일까요?"},danish:{about:"제시카 알렉산더와 이벤 산달이 덴마크의 육아 문화를 정리한 책으로 알려진 방향이에요. 놀이, 솔직함, 다시 보기, 공감, 최후통첩 없음, 함께함의 여섯 가지를 들어요. 함께 있는 편안한 시간인 휘게를 중요하게 보고, 아이와 이기고 지는 싸움을 만들지 않아요.",principles:["자유 놀이를 배움의 중심에 둬요.","좋은 일만 말하지 않고 나이에 맞게 솔직하게 말해요.","아이의 행동을 다른 말로 다시 봐요.","협박과 힘겨루기 대신 함께 있는 시간을 늘려요."],scenes:{tantrum:'"안 사면 집에 안 간다" 같은 말을 쓰지 않아요. "결심이 대단하네. 그런데 오늘은 안 사" 하고 곁에 있다가, 가라앉으면 다른 놀이로 넘어가요.',bedtime:"불을 낮추고 이야기하며 편안한 시간으로 만들어요. 재우려는 싸움이 되면 잠시 쉬었다가 다시 시작해요.",meal:"함께 앉아 있는 시간을 즐겁게 만드는 데 집중해요. 안 먹는 것을 문제 삼기보다 오늘 있었던 이야기를 나눠요."},ages:{baby:"많이 안고 말을 걸며, 온 가족이 함께 있는 저녁 시간을 만들어요.",toddler:'어른이 정하지 않은 놀이 시간을 충분히 둬요. 고집을 "결심이 분명하다"로 다시 말해 봐요.',preschool:"어려운 질문에 솔직하게 답하고, 슬픈 이야기도 피하지 않고 함께 읽어요."},takes:"돈은 거의 들지 않아요. 저녁 시간을 비우는 일이 맞벌이 집에는 어렵고, 지칠 때 협박을 참는 인내가 필요해요.",evidence:"책은 덴마크의 행복 지표와 육아 문화를 연결해 설명하지만, 이 여섯 가지를 묶어서 살핀 연구는 찾기 어려워요. 행복 지표에는 복지와 노동 환경도 함께 작용해요. 자유 놀이나 공감 같은 부분은 따로 연구가 있어요.",compass:"이기고 지는 싸움이 되지 않게 다르게 볼 말은 무엇일까요?"},positive:{about:"심리학자 아들러와 드라이커스의 생각을 교육자 제인 넬슨이 1981년 책으로 정리한 방식이에요. 아이의 문제 행동 뒤에는 소속되고 싶고 자기가 중요한 사람이고 싶은 마음이 있다고 봐요. 벌과 상을 모두 줄이고, 다정하면서도 단호하게 문제를 함께 풀어요.",principles:["다정함과 단호함을 함께 지켜요.","행동 뒤의 마음을 먼저 생각해 봐요.","벌 대신 해결 방법을 함께 정해요.","실수는 배울 기회로 삼고, 가족 회의로 함께 결정해요."],scenes:{tantrum:'"속상했구나. 그리고 오늘은 안 사." 가라앉으면 "다음에 가게 올 때 어떤 약속을 할까?" 하고 같이 정해요.',bedtime:'잠자리 순서표를 아이와 함께 만들어요. 버티면 "순서표에서 다음이 뭐지?" 하고 물어요.',meal:"메뉴 하나를 고르게 하거나 함께 준비하게 해요. 안 먹어도 벌을 주지 않고, 간식 약속은 가족이 함께 정한 대로 해요."},ages:{baby:"돌 전에는 벌이나 약속이 뜻이 없어요. 믿을 수 있는 반응과 일과를 만드는 시기예요.",toddler:'둘 중 고르게 하고, 할 일을 작게 맡겨서 "내가 도왔다"는 경험을 줘요.',preschool:"가족 회의를 짧게 시작하고, 함께 정한 약속이 안 지켜지면 다시 이야기해요."},takes:"이야기를 나누고 함께 정하는 시간이 많이 들어요. 어린 아이에게는 적용할 수 있는 폭이 좁고, 부모가 일관되게 함께해야 해요.",evidence:"여러 나라에서 널리 쓰이지만 통제된 비교 연구는 많지 않아요. 소규모 연구에서 부모의 태도가 달라졌다는 보고가 있어요. 벌을 줄이는 긍정적 양육 전반은 다른 프로그램에서 더 많이 연구됐어요.",compass:"이 행동 뒤의 마음은 무엇이고, 아이와 함께 정할 수 있는 것은 무엇일까요?"},attachment:{about:"윌리엄 시어스 부부가 볼비와 에인스워스의 애착 연구에서 영감을 받아 정리한 육아법이에요. 몸을 가까이하고 신호에 빠르게 답하면 아이가 세상을 믿게 되고, 그 믿음이 독립의 바탕이 된다고 봐요. 애착 이론 자체와 애착육아의 구체적 방법은 구분해서 봐야 해요.",principles:["아이의 신호에 빠르고 따뜻하게 답해요.","안고 업으며 몸을 가까이 둬요.","울음을 고쳐야 할 습관이 아니라 말로 들어요.","부모의 균형도 지켜요. 지치면 도움을 청해요."],scenes:{tantrum:"번쩍 안아 올려 조용한 곳으로 가요. 품에서 진정되면 무엇이 하고 싶었는지 묻고, 살 수 없는 것은 그때 말해요.",bedtime:"잠들 때까지 곁에 있어요. 같은 방에서 재우기도 하지만, 돌 전에는 부모 침대가 아닌 아기 잠자리에 등을 대고 눕혀요.",meal:"아이의 배고픔 신호를 먼저 봐요. 안 먹는 날에는 곁에 앉아 있어 주고, 먹이는 일이 다툼이 되지 않게 해요."},ages:{baby:"많이 안고 바로 달래요. 아기띠를 쓸 때는 얼굴이 보이고 숨길이 막히지 않게 해요.",toddler:"떨어질 때 언제 돌아오는지 말해 주고, 돌아와서는 충분히 안아 줘요.",preschool:"혼자 해 보려는 것을 응원하고, 힘들어 돌아오면 언제든 받아 줘요."},takes:"부모의 몸과 시간이 가장 많이 들어요. 잠이 부족해지기 쉽고, 한 사람에게 몰리지 않도록 나눠 맡을 사람이 있어야 해요.",evidence:"민감한 반응과 안정 애착이 함께 나타난다는 연구는 많아요. 하지만 아기띠, 같이 자기 같은 특정 방법이 안정 애착을 만든다는 근거는 약해요. 안정 애착은 여러 방식으로 만들어질 수 있어요.",compass:"아이가 지금 보내는 신호는 무엇이고, 어떻게 가까이 답할 수 있을까요?"},waldorf:{about:"루돌프 슈타이너가 1919년 독일 슈투트가르트의 공장 노동자 자녀를 위해 연 학교에서 시작됐어요. 어린 시기에는 글자보다 몸과 손, 상상으로 배운다고 보고, 매일 같은 리듬을 중요하게 여겨요. 나무와 천 같은 소박한 놀잇감과 옛이야기를 쓰고, 화면은 되도록 늦춰요.",principles:["하루와 계절의 리듬을 일정하게 지켜요.","어린 시기에는 글자보다 상상 놀이와 손 활동을 앞에 둬요.","어른이 하는 일을 곁에서 따라 하며 배워요.","화면과 완성된 장난감은 줄여요."],scenes:{tantrum:'말을 길게 하지 않고 조용히 데리고 나와요. 노래를 흥얼거리거나 "토끼처럼 살금살금 가 볼까" 하고 상상으로 다음 움직임을 열어 줘요.',bedtime:"씻기, 촛불 대신 작은 등 켜기, 같은 노래, 화면 없는 옛이야기 순서를 매일 똑같이 해요. 리듬이 말을 대신해요.",meal:"함께 음식을 만들고 짧은 노래나 인사로 시작해요. 먹으라고 설득하기보다 매일 같은 시간에 같은 흐름으로 앉아요."},ages:{baby:"조용한 환경과 일정한 하루를 만들고, 부드러운 목소리로 노래를 들려줘요.",toddler:"반죽, 빨래 개기처럼 어른의 일을 따라 하게 해요. 천과 나무토막으로 놀게 해요.",preschool:"옛이야기와 역할 놀이를 넓혀요. 글자는 서두르지 않지만 입학 준비는 학교와 맞춰 봐요."},takes:"화면 없는 시간을 만드는 데 집안 전체의 노력이 들어요. 원목 놀잇감은 비쌀 수 있지만 꼭 필요하지는 않아요. 초등 입학을 앞두고 글자를 늦춘 것이 걱정될 수 있어요.",evidence:"다른 학교와 엄밀하게 비교한 연구는 적어요. 미국 일부 연구에서는 저학년 시험 점수가 낮고 고학년에서 따라잡는 모습이 보고됐어요. 배경 사상인 인지학에는 과학적 근거가 없는 내용이 있어 가려서 볼 필요가 있어요.",compass:"오늘의 리듬을 지키면서 손과 상상으로 할 수 있는 것은 무엇일까요?"},reggio:{about:"2차 대전 뒤 이탈리아 레지오 에밀리아에서 부모들이 세운 유아 학교를 교육자 로리스 말라구치가 이끌며 만들어진 접근이에요. 아이를 유능한 탐구자로 보고, 말뿐 아니라 그림, 만들기, 몸짓처럼 백 가지 언어로 표현한다고 말해요. 정해진 교육과정 대신 아이의 관심을 따라가고 그 과정을 기록해요.",principles:["아이의 질문과 관심에서 시작해요.","여러 재료와 방법으로 생각을 표현하게 해요.","과정을 기록하고 함께 다시 보며 이어 가요.","공간도 배움을 돕는 교사처럼 꾸며요."],scenes:{tantrum:'가라앉은 뒤 "그게 왜 그렇게 좋았어?" 하고 물어요. 관심을 사는 것이 아니라 그림으로 그려 보거나 집에서 만들어 보는 것으로 이어 줘요.',bedtime:'오늘 궁금했던 것을 하나 나누고 적어 둬요. "내일 이어서 알아보자"로 하루를 맺어요. 자는 시간은 일정하게 지켜요.',meal:'"이건 왜 이런 색일까?" 하고 음식을 함께 살펴봐요. 장을 같이 보고 재료를 만져 보며 음식을 궁금한 대상으로 만들어요.'},ages:{baby:"무엇을 오래 보는지 관찰하고 사진과 글로 남겨요. 안전한 재료로 감각을 넓혀 줘요.",toddler:"좋아하는 것(자동차, 벌레)을 따라가요. 그림으로 그리고 사진을 같이 봐요.",preschool:'"왜?"를 함께 조사하는 작은 탐구로 키워요. 생각을 물어보고 아이의 말을 적어 둬요.'},takes:"아이를 관찰하고 기록하고 이어 갈 시간과 힘이 많이 들어요. 재료와 공간도 필요해요. 교사의 팀과 지역사회가 함께하는 접근이라 가정에서는 일부만 가져올 수 있어요.",evidence:"이탈리아의 성인을 살핀 비실험 연구에서, 보육을 받지 않은 경우보다는 나은 결과가 있었지만 다른 보육 기관과는 뚜렷한 차이가 드러나지 않았어요. 가정에서의 실천을 살핀 연구는 드물어요.",compass:"아이가 지금 궁금해하는 것은 무엇이고, 어떻게 함께 알아볼 수 있을까요?"}}}}]);